#!/bin/bash
# zeta: B4 remask/schedule/order sweep on the B1 adapter, B1 held-out, B6 step distillation from the B1 teacher.
cd ~/shigeru/open-mercury
M=runs/zeta_sft_final_e5/final; D=data/distill/phaseA_stage2c_train.jsonl; R=results/pure/dev_refs_sft3.json; L=results/pure/bdiff_chain.log
E="SHIGERU_GPU_GUARD=off CUDA_VISIBLE_DEVICES=0 PYTHONPATH=."
A=runs/bdiff_b1/adapter; T=runs/bdiff_b1/time_embed.pt
for b in 1 2 4; do for S in 16 8; do env $E .venv-train/bin/python bench/eval_bdiff.py --model $M --adapter $A --time-embed $T --refs $R --n 50 --steps $S --remask --remask-budget $b --skip-tf --out results/pure/bdiff_b1_remask${b}_S$S.json > results/pure/bdiff_b1_remask${b}_S$S.log 2>&1; echo "=== $(date +%T) [zeta] b4(b1) remask$b S$S $(grep -E '^=== bdiff_gen' results/pure/bdiff_b1_remask${b}_S$S.log | cut -c1-400)" >> $L; done; done
env $E .venv-train/bin/python bench/eval_bdiff.py --model $M --adapter $A --time-embed $T --refs $R --n 50 --steps 16,8 --schedule cosine --skip-tf --out results/pure/bdiff_b1_cosine_sampling.json > results/pure/bdiff_b1_cosine_sampling.log 2>&1; echo "=== $(date +%T) [zeta] b4(b1) cosine-sampling $(grep -E '^=== bdiff_gen' results/pure/bdiff_b1_cosine_sampling.log | cut -c1-400 | tr '\n' ' ')" >> $L
env $E .venv-train/bin/python bench/eval_bdiff.py --model $M --adapter $A --time-embed $T --refs $R --n 50 --steps 16,8 --orders random,left --skip-tf --out results/pure/bdiff_b1_orders.json > results/pure/bdiff_b1_orders.log 2>&1; echo "=== $(date +%T) [zeta] b4(b1) orders $(grep -E '^=== bdiff_gen' results/pure/bdiff_b1_orders.log | cut -c1-600 | tr '\n' ' ')" >> $L
env $E .venv-train/bin/python bench/eval_bdiff.py --model $M --adapter $A --time-embed $T --refs $R --skip 50 --n 150 --steps 16,8 --skip-tf --out results/pure/bdiff_b1_heldout.json > results/pure/bdiff_b1_heldout.log 2>&1; echo "=== $(date +%T) [zeta] b1 held-out 50-199 $(grep -E '^=== bdiff_gen' results/pure/bdiff_b1_heldout.log | cut -c1-500 | tr '\n' ' ')" >> $L
env $E .venv-train/bin/python distill/gen_bstates.py --mode samples --model $M --adapter $A --time-embed $T --data $D --limit 3000 --cuts 2 --steps 16 --out data/distill/bsamples_b1_s16.jsonl > results/pure/gen_bsamples_b1.log 2>&1; echo "=== $(date +%T) [zeta] b6 teacher samples rc=$? $(tail -n 1 results/pure/gen_bsamples_b1.log | cut -c1-200)" >> $L
env $E .venv-train/bin/python distill/train_bdiff.py --model $M --data $D --blocks data/distill/bsamples_b1_s16.jsonl --p-blocks 0.7 --init-adapter $A --t-min 0.5 --out runs/bdiff_b6 --steps 1500 --accum 8 --lr 1e-4 --save-every 500 > results/pure/train_bdiff_b6.log 2>&1; echo "=== $(date +%T) [zeta] b6 train rc=$? $(tail -n 2 results/pure/train_bdiff_b6.log | head -n1 | cut -c1-300)" >> $L
env $E .venv-train/bin/python bench/eval_bdiff.py --model $M --adapter runs/bdiff_b6/adapter --time-embed runs/bdiff_b6/time_embed.pt --refs $R --n 50 --steps 16,8,4 --skip-tf --out results/pure/bdiff_b6_eval.json > results/pure/bdiff_b6_eval.log 2>&1; echo "=== $(date +%T) [zeta] b6 eval rc=$? $(grep -E '^=== bdiff_gen' results/pure/bdiff_b6_eval.log | cut -c1-600 | tr '\n' ' ')" >> $L
echo "=== $(date +%T) [zeta] b chain2 done" >> $L
